using MegaCrit.Sts2.Core.Nodes;

namespace CombatSolver;

internal sealed partial class UnattendedTestRunner
{
    private async Task RunTaskTaintedContinuationAsync(CombatState live, Player player)
    {
        foreach (var relic in player.Relics.ToArray()) await RelicCmd.Remove(relic);
        await ClearPlayerPilesAsync(player);
        await PowerCmd.Apply<VitalSparkPower>(new BlockingPlayerChoiceContext(), live.Enemies.First(), 3, null, null);
        foreach (string id in new[] { "DREDGE", "ACROBATICS", "DISCOVERY" })
        foreach (int upgrade in new[] { 0, 1 })
        {
            await ClearPlayerPilesAsync(player);
            await InjectCardAsync(live, player, new() { CardId = id, UpgradeLevels = upgrade, Pile = "Hand" });
            foreach (string other in new[] { "STRIKE_SILENT", "DEFEND_SILENT" })
                await InjectCardAsync(live, player, new() { CardId = other, Pile = "Hand" });
            foreach (string other in new[] { "BACKFLIP", "FINESSE", "STRIKE_SILENT", "DEFEND_SILENT" })
                await InjectCardAsync(live, player, new() { CardId = other, Pile = "Draw" });
            foreach (string other in new[] { "BASH", "STRIKE_IRONCLAD", "DEFEND_IRONCLAD", "DEFEND_DEFECT" })
                await InjectCardAsync(live, player, new() { CardId = other, Pile = "Discard" });
            SetEnergy(player, 30);
            var nativeCard = player.PlayerCombatState!.Hand.Cards.Single(c => c.Id.Entry == id);
            if (nativeCard.Affliction is not Tainted) throw new InvalidOperationException("Native Vital Spark did not afflict " + id);
            CombatRootSnapshot root = CombatRootSnapshot.Capture(live);
            SolverDisplayNames names = SolverDisplayNames.Capture(live);
            var parent = root.ForkSimulator();
            PredictedCard Card(CombatPredictionSimulator sim) => sim.State.FindCard(nativeCard)!;
            string Stamp(CombatPredictionSimulator sim) => DescribeContinuationContractState(sim, root, player);
            void Equal(string expected, string actual, string label)
            {
                if (expected != actual) throw new InvalidOperationException(id + "+" + upgrade + " " + label + "\nEXPECTED\n" + expected + "\nACTUAL\n" + actual);
            }
            void Finish(CombatPredictionSimulator sim, ForkableSet<uint> deaths)
            {
                var combat = (SimulatedCombatState)sim.State.CombatState;
                if (!CorePowerSupport.ApplyEnemyDeathPowers(sim, combat, combat.KnownEnemies, deaths)
                    || !CombatBeamSolver.SettleReplayActionBoundary(sim, combat))
                    throw new InvalidOperationException("Unexpected post-action selector.");
                sim.CheckWinCondition(root.StartTurnNumber);
            }
            CombatPredictionSimulator Legacy(IReadOnlyList<PlanCardChoice>? plans)
            {
                using var isolation = SimulationNotificationIsolation.Enter();
                var sim = parent.Fork();
                var combat = (SimulatedCombatState)sim.State.CombatState;
                ForkableSet<uint> deaths = [];
                combat.BeginActionChoices(plans);
                try
                {
                    using (combat.BeginCardExecutionScope(deaths))
                        if (sim.ManualPlay(Card(sim), null, out _)) Finish(sim, deaths);
                }
                finally { combat.EndActionChoices(); }
                return sim;
            }
            string parentBefore = Stamp(parent), liveBefore = ContinuationStamp.CaptureLive(live).StateText;
            var discovery = Legacy(null);
            var request = ((SimulatedCombatState)discovery.State.CombatState).PendingTurnStartChoice
                ?? throw new InvalidOperationException("Expected choice for " + id);
            var choices = CardChoiceSupport.BuildChoices(request.Spec!, names, 64, 64)
                .Select(c => c with { SourceId = request.SourceId, ContextId = request.ContextId, Timing = request.Timing }).ToArray();
            var seed = parent.Fork();
            CardContinuationContractCheckpoint? captured;
            using (SimulationNotificationIsolation.Enter())
                captured = CaptureCardContinuationContract(seed, Card(seed), null, []);
            using var checkpoint = captured ?? throw new InvalidOperationException("Failed Tainted capture " + id);
            CombatPredictionSimulator Resume(int index)
            {
                using var isolation = SimulationNotificationIsolation.Enter();
                var child = checkpoint.Resume([choices[index]], CancellationToken.None);
                if (!child.Completed) throw new InvalidOperationException("Unexpected nested selector.");
                Finish(child.Simulator, child.Deaths);
                return child.Simulator;
            }
            var references = choices.Select(choice => Stamp(Legacy([choice]))).ToArray();
            for (int index = choices.Length - 1; index >= 0; index--)
            {
                var child = Resume(index);
                Equal(references[index], Stamp(child), "complete state/history/RNG");
                if (((SimulatedCombatState)child.State.CombatState).GetAmount<TaintedPower>(player.Creature) <= 0)
                    throw new InvalidOperationException("AfterCardPlayed did not apply TaintedPower.");
            }
            var first = Resume(0);
            using (SimulationNotificationIsolation.Enter())
            {
                first.Afflict<Tainted>(Card(first), 19);
                ((SimulatedCombatState)first.State.CombatState).SetAmount<VitalSparkPower>(live.Enemies.First(), 7);
            }
            Equal(references[0], Stamp(Resume(0)), "sibling affliction and power isolation");
            var parallel = await Task.WhenAll(Enumerable.Range(0, 16).Select(i => Task.Run(() => Stamp(Resume(i % choices.Length)))));
            for (int i = 0; i < parallel.Length; i++) Equal(references[i % choices.Length], parallel[i], "DOP16");
            var nativeAmount = nativeCard.Affliction!.Amount;
            CombatPredictionSimulator liveProbe;
            try
            {
                nativeCard.Affliction.Amount += 11;
                liveProbe = Resume(0);
                // The existing diagnostic history formatter intentionally describes
                // Original model identities using live card metadata. Branch state,
                // fingerprint, RNG and owned CardPlay must remain independently frozen.
                Equal(references[0].Split("\nHISTORY=", 2)[0], Stamp(liveProbe).Split("\nHISTORY=", 2)[0], "live full branch isolation");
                if (Card(liveProbe).Preview.Affliction?.Amount != nativeAmount)
                    throw new InvalidOperationException("Live affliction entered branch preview.");
                var started = liveProbe.History.OfType<CombatPredictionCardPlayStartedEntry>().Single();
                var finished = liveProbe.History.OfType<CombatPredictionCardPlayFinishedEntry>().Single();
                if (!ReferenceEquals(started.CardPlay, finished.CardPlay)
                    || !ReferenceEquals(started.Trace, finished.Trace)
                    || !ReferenceEquals(started.CardPlay.Card, Card(liveProbe).Preview))
                    throw new InvalidOperationException("Owned play/trace/card mapping changed with live metadata.");
                foreach (var draw in liveProbe.History.OfType<CombatPredictionCardDrawnEntry>())
                    if (!ReferenceEquals(liveProbe.History.GetResolvedEntry<CombatPredictionCardDrawResolvedEntry>(draw).OriginalEntry, draw))
                        throw new InvalidOperationException("Owned deferred draw mapping changed.");
            }
            finally { nativeCard.Affliction.Amount = nativeAmount; }
            Equal(references[0], Stamp(liveProbe), "full history after restoring original identity metadata");
            Equal(parentBefore, Stamp(parent), "parent isolation");
            Equal(liveBefore, ContinuationStamp.CaptureLive(live).StateText, "live restored");
            var expected = Legacy([choices[0]]);
            string expectedNative = ContinuationStamp.CapturePredicted(player, expected, root.StartTurnNumber, root.Forecast, root.StartTurnNumber).StateText;
            using CancellationTokenSource deadline = new(TimeSpan.FromSeconds(12));
            using var session = NativeChoiceRuntime.Begin(live, player, "test:tainted-card-continuation");
            session.SetPlanAndStartDriving(NGame.Instance!, [choices[0] with { SourceId = id }], deadline.Token);
            GameAction action = await SolverController.EnqueueAndCaptureActionAsync(
                queued => queued is PlayCardAction played && ReferenceEquals(played.NetCombatCard.ToCardModelOrNull(), nativeCard),
                () => { if (!nativeCard.TryManualPlay(null)) throw new InvalidOperationException("Native Tainted card not playable."); }, deadline.Token);
            await session.AwaitProducerAndCompleteAsync(action.CompletionTask).WaitAsync(deadline.Token);
            Equal(expectedNative, ContinuationStamp.CaptureLive(live).StateText, "native full continuation");
            _completedChecks.Add($"TaintedContinuation:{id}+{upgrade}:choices={choices.Length}:full-state-history-RNG:parent-live-sibling:DOP16:native-callback");
        }
    }
}

